 "content": "from collections import Counter


def _periodic_score(indices):
    if len(indices) < 2:
        return 0
    best = 0
    vals = sorted(indices)
    for i in range(len(vals)):
        for j in range(i + 1, len(vals)):
            step = vals[j] - vals[i]
            if step < 2:
                continue
            count = 1
            p = vals[i]
            while p + step in indices:
                p += step
                count += 1
            best = max(best, count if count >= 2 else 0)
    return best


def transform(grid):
    h, w = len(grid), len(grid[0])
    row_modes = {}
    for r, row in enumerate(grid):
        color, n = Counter(row).most_common(1)[0]
        if n / w >= 0.75:
            row_modes.setdefault(color, set()).add(r)
    col_modes = {}
    for c in range(w):
        color, n = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if n / h >= 0.70:
            col_modes.setdefault(color, set()).add(c)
    candidates = set(row_modes) & set(col_modes)
    rail_color = max(candidates, key=lambda color: (
        _periodic_score(row_modes[color]) * _periodic_score(col_modes[color]),
        _periodic_score(row_modes[color]) + _periodic_score(col_modes[color])))
    rows = sorted(row_modes[rail_color])
    cols = sorted(col_modes[rail_color])
    marked = [(ri, ci) for ri, r in enumerate(rows) for ci, c in enumerate(cols)
              if grid[r][c] != rail_color]
    r0, r1 = min(ri for ri, _ in marked), max(ri for ri, _ in marked)
    c0, c1 = min(ci for _, ci in marked), max(ci for _, ci in marked)
    vertices = [[grid[rows[ri]][cols[ci]] for ci in range(c0, c1 + 1)]
                for ri in range(r0, r1 + 1)]
    background = Counter(v for row in grid for v in row
                         if v != rail_color and v not in (0,)).most_common(1)[0][0]
    # Non-lattice area identifies the fill (the most common cell outside rails).
    rail_rows, rail_cols = set(rows), set(cols)
    fill_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                          if r not in rail_rows and c not in rail_cols)
    background = fill_counts.most_common(1)[0][0]
    return [[vertices[r][c] if len({vertices[r][c], vertices[r][c+1],
                                   vertices[r+1][c], vertices[r+1][c+1]}) == 1
             else background for c in range(len(vertices[0])-1)]
            for r in range(len(vertices)-1)]


