def transform(grid):
    h, w = len(grid), len(grid[0])
    # Candidate rails are lines with a dominant color. True rail colors produce
    # repeated horizontal and vertical lines, with sparse edited intersections;
    # ordinary field-color lines do not have such edited crossings.
    row_candidates = {}
    for r, row in enumerate(grid):
        color, n = Counter(row).most_common(1)[0]
        if n / w >= 0.50:
            row_candidates.setdefault(color, []).append(r)
    col_candidates = {}
    for c in range(w):
        color, n = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if n / h >= 0.50:
            col_candidates.setdefault(color, []).append(c)

    colors = set(row_candidates) & set(col_candidates)
    def score(color):
        rs, cs = row_candidates[color], col_candidates[color]
        altered = sum(grid[r][c] != color for r in rs for c in cs)
        return (altered, min(len(rs), len(cs)), len(rs) + len(cs))
    rail_color = max(colors, key=score)
    rows, cols = row_candidates[rail_color], col_candidates[rail_color]

    marked = [(ri, ci) for ri, r in enumerate(rows) for ci, c in enumerate(cols)
              if grid[r][c] != rail_color]
    if not marked:
        return []
    r0, r1 = min(ri for ri, _ in marked), max(ri for ri, _ in marked)
    c0, c1 = min(ci for _, ci in marked), max(ci for _, ci in marked)
    vertices = [[grid[rows[ri]][cols[ci]] for ci in range(c0, c1 + 1)]
                for ri in range(r0, r1 + 1)]

    # The dominant non-rail color in the periodic field is the mixed-cell fill.
    field_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                           if r not in set(rows) and c not in set(cols))
    default = field_counts.most_common(1)[0][0]
    return [[vertices[r][c] if len({vertices[r][c], vertices[r][c+1],
                                    vertices[r+1][c], vertices[r+1][c+1]}) == 1
             else default for c in range(len(vertices[0]) - 1)]
            for r in range(len(vertices) - 1)]


if __name__ == '__main__':
    # Execute on the current instance, with the supplied lattice intersections.
    g = [[3] * 25 for _ in range(29)]
    rr, cc = (0, 7, 14, 21, 28), (0, 11, 22)
    for r in range(29):
        for c in range(25):
